  [UnityTest,Timeout(290000)]public IEnumerator FourRealAiUseAllSixToolsExtractCorrectToothAnimatePatientFinishPauseRematch(){using(var f=new Fixture()){yield return f.Load();f.Start();string id=(string)Get(f.match,"MatchId");Time.timeScale=3;bool paused=false,captured=false;float maxAngle=0,minAngle=100;float end=Time.realtimeSinceStartup+240;while(!(bool)Get(f.match,"Finished")&&Time.realtimeSinceStartup<end){f.Observe();float angle=(float)Get(Get(f.match,"patient"),"AnimationAngle");minAngle=Mathf.Min(minAngle,angle);maxAngle=Mathf.Max(maxAngle,angle);if(!paused&&(int)Get(f.match,"CorrectSteps")>0){paused=true;Call(f.match,"Pause",0,false);float clock=(float)Get(f.rules,"Clock");var positions=f.trucks.Select(Body).Select(b=>b.position).ToArray();var stages=((int[])Get(f.rules,"stage")).ToArray();yield return new WaitForSecondsRealtime(.2f);Assert.That((float)Get(f.rules,"Clock"),Is.EqualTo(clock));Assert.That((int[])Get(f.rules,"stage"),Is.EqualTo(stages));for(int i=0;i<4;i++)Assert.That(Vector3.Distance(positions[i],Body(f.trucks[i]).position),Is.LessThan(.001f));Call(f.match,"Resume");Time.timeScale=3;}if(!captured&&(int)Get(f.match,"CorrectExtractions")>0){captured=true;Time.timeScale=1;yield return Capture(f.match,"natural-AI-real-extraction-720",1280,720);yield return Capture(f.match,"natural-AI-real-extraction-1080",1920,1080);Time.timeScale=3;}yield return null;}f.Observe();Assert.That((bool)Get(f.match,"Finished"),Is.True);Assert.That((int[])Get(f.match,"ToolContactCounts"),Is.All.GreaterThan(0),"All six selected tools must have actual native collision/overlap contacts.");Assert.That((int)Get(f.match,"CorrectSteps"),Is.GreaterThan(0));Assert.That((int)Get(f.match,"CorrectExtractions"),Is.GreaterThan(0),"A correct rinsed loose tooth requires an actual clamped socket joint break.");Assert.That(((int[])Get(f.rules,"procedures")).Sum(),Is.GreaterThan(0));Assert.That(paused&&captured,Is.True);Assert.That(maxAngle-minAngle,Is.GreaterThan(1),"The original patient actually animates; no frozen character claim.");Assert.That((int)Get(Get(f.match,"ScoreJournal"),"Count"),Is.GreaterThan(0));f.Start();Assert.That((string)Get(f.match,"MatchId"),Is.Not.EqualTo(id));Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);Assert.That((int[])Get(f.rules,"procedures"),Is.All.Zero);Assert.That(f.teeth.All(t=>!(bool)Get(t,"Broken")&&!(bool)Get(t,"Extracted")&&Mathf.Abs((float)Get(t,"Health")-100)<.001f),Is.True);}}
  [UnityTest,Timeout(25000)]public IEnumerator SixOriginalSelectedToolsExtendTogetherBeyondOriginalTrayBeforeActualToothContact(){using(var f=new Fixture()){yield return f.Load();f.Start();int contacts=(int)Get(f.match,"NativeToolContacts");for(int i=0;i<4;i++){var arm=f.arms[i];var grip=(Rigidbody)Get(arm,"grip");var models=(Transform[])Get(f.tools[i],"models");var tips=(SphereCollider[])Get(f.tools[i],"tips");var tray=grip.transform.Find("Machined articulated support tray");Assert.That(tray.localScale,Is.EqualTo(new Vector3(2.8f,.14f,2.8f)));Assert.That(tray.localPosition,Is.EqualTo(new Vector3(0,-.35f,0)));var shape=tray.GetComponent<BoxCollider>();float trayFront=tray.localPosition.z+(shape.center.z+shape.size.z*.5f)*tray.localScale.z;var originalTeeth=f.teeth.Skip(i*4).Take(4).Select(t=>(Joint)Get(t,"Socket")).ToArray();for(int k=0;k<6;k++){Kind(f.tools[i],((Array)Enum.GetValues(Get(f.tools[i],"Kind").GetType())).GetValue(k).ToString());Assert.That(models[k].localPosition,Is.EqualTo(Vector3.forward*1.2f));Assert.That(tips[k].transform,Is.EqualTo(models[k]));Assert.That(tips[k].center,Is.EqualTo(new Vector3(0,0,.85f)));var tip=grip.transform.InverseTransformPoint((Vector3)Get(f.tools[i],"Tip"));Assert.That(tip.z,Is.EqualTo(2.05f).Within(.0001f));Assert.That(tip.z+tips[k].radius-trayFront,Is.GreaterThan(.5f),"Actual selected native contact reaches the tooth before the unchanged solid wrist tray.");Assert.That(models.Count(m=>m.gameObject.activeSelf),Is.EqualTo(1));}Assert.That(f.teeth.Skip(i*4).Take(4).Select(t=>(Joint)Get(t,"Socket")),Is.EqualTo(originalTeeth));}Assert.That((int)Get(f.match,"NativeToolContacts"),Is.EqualTo(contacts),"Geometry inspection cannot fabricate actual contact or scores.");Assert.That((int[])Get(f.rules,"points"),Is.All.Zero);TestContext.WriteLine("DENTIST_ACTUAL_SAVED_TOOL_GEOMETRY24 model/collider roots; original native water/drill/extraction and fourAI tests still required.");}}
  [UnityTest,Timeout(25000)]public IEnumerator ReadOnlyActualToothSocketSelectedTipAndNativeCallbacksDiagnostic(){using(var f=new Fixture()){yield return f.Load();f.Start();foreach(var arm in f.arms)((Rigidbody)Get(arm,"grip")).gameObject.AddComponent<DentistContactDiagnosticObserver>();float end=Time.realtimeSinceStartup+12,next=0;while((float)Get(f.rules,"Clock")<12&&Time.realtimeSinceStartup<end){if(Time.realtimeSinceStartup>=next){next=Time.realtimeSinceStartup+.5f;f.Observe(-1,true);}yield return null;}f.Observe(-1,true);yield return Capture(f.match,"read-only-natural-tooth-tool-geometry-720",1280,720);Assert.That((float)Get(f.rules,"Clock"),Is.GreaterThan(8));TestContext.WriteLine("DENTIST_READ_ONLY_NATIVE diagnostics only: no procedure/contact success inferred from this test; all original contact and full-match criteria remain.");}}
