ll(f.teeth[2],"Tick");Assert.That((int)Get(f.match,"CorrectExtractions"),Is.EqualTo(extracted));Assert.That(((int[])Get(f.rules,"points"))[0],Is.EqualTo(points));yield return Capture(f.match,"controlled-actual-contact-and-socket-720",1280,720);f.match.enabled=true;}}
